export interface ThemeMeta {
  id: ThemeId;
  label: string;
  group: string;
}

export const themeList: readonly ThemeMeta[] = [
  { id: "sage", label: "养生绿", group: "品牌" },
  { id: "spring", label: "春 · 新芽", group: "季节" },
  { id: "summer", label: "夏 · 青荷", group: "季节" },
  { id: "autumn", label: "秋 · 琥珀", group: "季节" },
  { id: "winter", label: "冬 · 苏木", group: "季节" },
] as const;

export type ThemeId =
  | "sage"
  | "spring"
  | "summer"
  | "autumn"
  | "winter";

export const defaultThemeId: ThemeId = "sage";

export const themeIds = themeList.map((t) => t.id) as readonly ThemeId[];

export function isThemeId(v: unknown): v is ThemeId {
  return typeof v === "string" && (themeIds as readonly string[]).includes(v);
}

/** 当前活动主题的色值快照 (取默认主题; 运行时换肤请看 CSS 变量, 这里只是静态参考) */
export const defaultThemeColors = themeColors[defaultThemeId];

export const defaultChartColors = chartColors[defaultThemeId];

